import React from 'react';
import styled from 'styled-components';

interface ButtonProps {
  primary?: boolean;
  size?: 'small' | 'medium' | 'large';
  label: string;
  onClick?: () => void;
}

const StyledButton = styled.button<{ primary?: boolean; size?: string }>`
  background-color: ${props => props.primary ? '#1ea7fd' : '#ffffff'};
  color: ${props => props.primary ? '#ffffff' : '#333333'};
  font-size: ${props => {
    switch (props.size) {
      case 'small': return '12px';
      case 'large': return '18px';
      default: return '14px';
    }
  }};
  padding: ${props => {
    switch (props.size) {
      case 'small': return '8px 16px';
      case 'large': return '16px 24px';
      default: return '12px 20px';
    }
  }};
  border: 1px solid ${props => props.primary ? '#1ea7fd' : '#cccccc'};
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    background-color: ${props => props.primary ? '#106ba3' : '#f8f8f8'};
  }
`;

export const Button: React.FC<ButtonProps> = ({
  primary = false,
  size = 'medium',
  label,
  ...props
}) => {
  return (
    <StyledButton
      primary={primary}
      size={size}
      {...props}
    >
      {label}
    </StyledButton>
  );
};

export default Button;
